function signature(){const s=game.state;return [s.money,s.lives,s.overtime,eveningMinutes(),s.wave,s.active,s.ended,s.event?.id,s.eventUntil,Math.ceil(s.rollback),game.selectedType,game.selectedSlot,game.paused,game.speed,s.towers.map(t=>`${t.slot}:${t.level}:${t.branch}`).join(','),modal,waveExpanded,popoverDetails,performance.now()<(game.routePreviewUntil||0),toast&&performance.now()<toastUntil].join('|');}
function animate(ts){const dt=(ts-last)/1000;last=ts;game.update(dt);game.updateFeedback(dt);const sig=signature();if(dirty||ts<overtimeUntil||sig!==lastSignature||(game.state.won&&ts-celebrationStarted<1800&&!matchMedia('(prefers-reduced-motion: reduce)').matches)){worldImage=renderWorld();renderUI();lastSignature=sig;dirty=false;}else if((!modal&&ts<(game.routePreviewUntil||0))||(game.state.active&&!game.paused)||game.feedback.length>0||(game.selectedSlot>=0&&!modal&&!game.state.ended)){battle.paint(game);world.batchDraw();}requestAnimationFrame(animate);}
function focusControl(){overlay.find('.keyboard-focus').forEach(n=>n.destroy());const c=controls[focusIndex];if(!c)return;const b=c.node.getClientRect({relativeTo:stage});overlay.add(new K.Rect({name:'keyboard-focus',x:b.x-3,y:b.y-3,width:b.width+6,height:b.height+6,stroke:'#ecaf29',strokeWidth:3,cornerRadius:7,listening:false}));document.getElementById('announcement').textContent=c.label;overlay.batchDraw();}
window.addEventListener('keydown',e=>{if(!game)return;if(e.key==='Tab'){e.preventDefault();focusIndex=(focusIndex+(e.shiftKey?-1:1)+controls.length)%controls.length;focusControl();return;}if(e.key==='Enter'&&focusIndex>=0){e.preventDefault();controls[focusIndex]?.action();dirty=true;return;}if(e.key==='Escape'){if(modal)closeModal();else{game.selectedSlot=-1;dirty=true;}return;}if(modal||game.state.ended)return;if(e.code==='Space'){e.preventDefault();game.paused=!game.paused;dirty=true;}if(/^[1-5]$/.test(e.key))game.chooseType(+e.key-1);if(e.key.startsWith('Arrow')){e.preventDefault();keySlot=(keySlot+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)+game.map.slots.length)%game.map.slots.length;toast=`已选择工位 ${keySlot+1} · 按 B 预览/查看`;toastUntil=performance.now()+2400;dirty=true;}if(e.key.toLowerCase()==='b')game.slot(keySlot);if(e.key.toLowerCase()==='u')game.upgrade();if(e.key.toLowerCase()==='r')game.rollback();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&game?.state.active){game.paused=true;dirty=true;}});window.addEventListener('resize',()=>{resize();if(!game&&loadingScreen)loadingScreen.draw(layout);});
function notifyArtFailure(){toast='概念原画暂时无法加载，请稍后刷新重试';toastUntil=performance.now()+3500;dirty=true;}
const assetPromises={};let loadingScreen;
function loadAsset(name){if(assets[name])return Promise.resolve(assets[name]);if(assetPromises[name])return assetPromises[name];assetPromises[name]=new Promise((resolve,reject)=>{const im=new Image(),timer=setTimeout(()=>{im.onload=null;im.onerror=null;reject(new Error('加载超时：'+name));},30000);im.onload=()=>{clearTimeout(timer);assets[name]=im;resolve(im);};im.onerror=()=>{clearTimeout(timer);reject(new Error('素材加载失败：'+name));};im.src='assets/'+name+'.webp';});return assetPromises[name];}
function enterGame(){if(game)return;game=new Game(event);try{game.records=JSON.parse(localStorage.getItem('evening-records-v2')||'{}');}catch{}if(!game.records||typeof game.records!=='object'||Array.isArray(game.records))game.records={};campaignRecords=loadCampaigns(LEVELS,game.records);saveCampaigns(campaignRecords);battle=new BattleRenderer(assets);game.routePreviewUntil=performance.now()+4500;resize();const url=new URL(location.href);if(url.searchParams.has('preview')){url.searchParams.delete('preview');history.replaceState(null,'',url);}requestAnimationFrame(animate);}
async function boot(){resize();loadingScreen=new LoadingScreen(stage,backdrop,ui,assets,enterGame,()=>location.reload());loadingScreen.state.preview=new URLSearchParams(location.search).get('preview')==='loading';loadingScreen.draw(layout);try{await Promise.allSettled(['loading-logo','loading-art'].map(name=>loadAsset(name).then(()=>loadingScreen.draw(layout))));const names=['dev','pm','design','qa','ops','environment','ground','road','enemies','ui','office-ground','office-environment','event-buff','event-debuff','faction-byte','faction-tencent','faction-ali','modal-frame-v22','button-primary-v22','button-secondary-v22','result-home-v22'];loadingScreen.state.total=names.length;loadingScreen.state.status='伙伴们正在就位…';loadingScreen.draw(layout);await Promise.all(names.map(name=>loadAsset(name).then(()=>{loadingScreen.state.ready++;loadingScreen.draw(layout);})));loadingScreen.state.status='园区已就绪，今天也要准点下班';if(loadingScreen.state.preview)loadingScreen.draw(layout);else enterGame();}catch(e){loadingScreen.state.failed=true;loadingScreen.draw(layout);document.getElementById('announcement').textContent=e.message;}}
